import { useCallback, useMemo, useState } from "react";
import { AgGridProvider, AgGridReact } from "ag-grid-react";
import type { CellSelectionOptions, ColDef, GetRowIdParams } from "ag-grid-community";
import { AllEnterpriseModule } from "ag-grid-enterprise";

const modules = [AllEnterpriseModule];

interface Line {
  id: number;
  product: string;
  price: number;
  quantity: number;
  total: string | number;
}

export function SpreadsheetGrid() {
  const [rowData] = useState<Line[]>([
    { id: 1, product: "Apples", price: 1.25, quantity: 4,
      total: '=REF(COLUMN("price"),ROW(1))*REF(COLUMN("quantity"),ROW(1))' },
    { id: 2, product: "Oranges", price: 0.8, quantity: 6,
      total: '=REF(COLUMN("price"),ROW(2))*REF(COLUMN("quantity"),ROW(2))' },
  ]);

  const columnDefs = useMemo<ColDef<Line>[]>(() => [
    { field: "product" },
    { field: "price" },
    { field: "quantity" },
    { field: "total", allowFormula: true },
  ], []);

  const defaultColDef = useMemo<ColDef<Line>>(() => ({ editable: true, flex: 1 }), []);

  // Excel-style ranges plus a fill handle on the selection
  const cellSelection = useMemo<CellSelectionOptions>(() => ({ handle: { mode: "fill" } }), []);

  // Formulas need stable row IDs
  const getRowId = useCallback((p: GetRowIdParams<Line>) => String(p.data.id), []);

  return (
    <AgGridProvider modules={modules}>
      <div style={{ height: 400 }}>
        <AgGridReact<Line>
          rowData={rowData}
          columnDefs={columnDefs}
          defaultColDef={defaultColDef}
          cellSelection={cellSelection}
          getRowId={getRowId}
          undoRedoCellEditing
          undoRedoCellEditingLimit={20}
        />
      </div>
    </AgGridProvider>
  );
}
